#!/bin/bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd -P)"
PORT=19494

resolve_exec() {
  local candidate
  for candidate in "$@"; do
    if [ -x "$candidate" ] && [ -f "$candidate" ]; then
      printf '%s' "$candidate"
      return 0
    fi
  done
  return 1
}

NODE="$(resolve_exec /opt/homebrew/bin/node /usr/local/bin/node /usr/bin/node)" || {
  printf '%s\n' 'Node is required to run this view-only preview.' >&2
  exit 13
}

printf '%s\n' 'VexLife Product Spiral VIEW ONLY'
printf '%s\n' 'Exact generated bytes; Product service/model/Home/Conversation are not connected.'
printf '%s\n' 'Preview: http://127.0.0.1:19494/'
printf '%s\n' 'Press Control-C in this Terminal to stop the preview.'

"$NODE" --input-type=module - "$ROOT" "$PORT" <<'NODEVIEW'
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { spawn } from 'node:child_process';

const [root, rawPort] = process.argv.slice(2);
const port = Number(rawPort);
const allowed = new Map([
  ['index.html', 'text/html; charset=utf-8'],
  ['vexweb.css', 'text/css; charset=utf-8'],
  ['vexweb.js', 'text/javascript; charset=utf-8'],
  ['vexweb-manifest.json', 'application/json; charset=utf-8'],
]);

const send = (res, status, type, body, headOnly = false) => {
  res.statusCode = status;
  res.setHeader('Content-Type', type);
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; connect-src 'self'; frame-src 'none'; worker-src 'none'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self';"
  );
  res.end(headOnly ? undefined : body);
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url ?? '/', 'http://127.0.0.1:' + port);
  const headOnly = req.method === 'HEAD';

  if (url.pathname.startsWith('/api/')) {
    send(
      res,
      503,
      'application/json; charset=utf-8',
      JSON.stringify({ message: 'VIEW_ONLY_PREVIEW_NO_PRODUCT_SERVICE' }),
      headOnly,
    );
    return;
  }

  if (req.method !== 'GET' && req.method !== 'HEAD') {
    send(
      res,
      405,
      'application/json; charset=utf-8',
      JSON.stringify({ message: 'VIEW_ONLY_PREVIEW_READ_ONLY' }),
      headOnly,
    );
    return;
  }

  const name = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
  const type = allowed.get(name);
  if (!type) {
    send(res, 404, 'text/plain; charset=utf-8', 'Not found', headOnly);
    return;
  }

  const file = path.join(root, name);
  if (!fs.existsSync(file) || !fs.statSync(file).isFile()) {
    send(res, 404, 'text/plain; charset=utf-8', 'Not found', headOnly);
    return;
  }

  send(res, 200, type, fs.readFileSync(file), headOnly);
});

server.listen(port, '127.0.0.1', () => {
  console.log('VIEW_ONLY_READY http://127.0.0.1:' + port + '/');
  const opener = spawn('/usr/bin/open', ['http://127.0.0.1:' + port + '/'], {
    stdio: 'ignore',
    detached: true,
  });
  opener.unref();
});

const stop = () => server.close(() => process.exit(0));
process.on('SIGINT', stop);
process.on('SIGTERM', stop);
NODEVIEW

VIEWSCRIPT
